return-response.set-body:
@{
                var r = new Random();
                return "{\"id\":\"" + context.Request.MatchedParameters["id"] + "\",\"price\":" + r.Next(20, 500) + "." + r.Next(0, 99).ToString("00") + ",\"currency\":\"EUR\",\"client\":\"" + context.Request.Headers.GetValueOrDefault("X-Client-Id", "") + "\"}";
            }
